    try:
        obj = json.loads(line)
        role = obj.get('role', '?')
        ts = obj.get('timestamp', '')
        if role == 'tool':
            name = ''
            c = obj.get('content', '')
            if isinstance(c, list):
                for item in c:
                    if isinstance(item, dict) and item.get('type') == 'tool_use':
                        name = item.get('name', '')
                        inp = str(item.get('input', ''))[:150]
                        print(f'[{ts}] TOOL_CALL: {name} → {inp}')
            elif isinstance(c, str):
                print(f'[{ts}] tool: {c[:200]}')
        elif role == 'tool_result':
            c = str(obj.get('content', ''))[:200]
            print(f'[{ts}] RESULT: {c}')
        elif role == 'assistant':
            c = str(obj.get('content', ''))[:200]
            print(f'[{ts}] ASSISTANT: {c}')
        elif role == 'user':
            c = str(obj.get('content', ''))[:200]
            print(f'[{ts}] USER: {c}')
    except Exception as e:
        pass
